/// <summary>
///     The <c>KCS_KBVRequestTable</c> class is the extension of table <c>common</c>
/// </summary>
public class KCS_KBVRequestTable extends common
{
}

Method.Source:
/// <summary>
///    AVA <c>initValue</c> method.
/// </summary>
public void initValue()
{
    date    locToday;
    str     sDate;

    #define.Hint('vom ');

    locToday    = AVAKBVBuildingProjectHelper::getToday();

    sDate       = #Hint;
    sDate       += date2Str(locToday, 123, 2, -1, 2, -1, 4);

    super();

    this.KCS_KBVRequestID       = '';
    this.CustRef                = sDate;
    this.KCS_KBVPriority        = KCS_KBVPriority::Normal;
    this.KCS_KBVReceiptDate     = locToday;
    this.KCS_KBVRequestStatus   = KCS_KBVRequestStatus::Created;
    this.NDX_OriginDataAreaId   = ''; //NDX_KBVOriginDataArea::find(this.DataAreaId).NDX_KBVOriginDataAreaId;
}

/// <summary>
///    AVA <c>initValueCopyToUC</c> method.
/// </summary>
/// <param name="_kcs_KBVRequestTableToCopy">
///    <c>KCS_KBVRequestTable</c> as type
/// </param>
/// <param name="_dataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
public void initValueCopyToUC(KCS_KBVRequestTable _kcs_KBVRequestTableToCopy, DataAreaId _dataAreaId = curExt())
{
    DataAreaId                          locDataAreaIdCurExt;
    AVASalesParameters                  locAVASalesParameters;
    AVASecondaryDataAreaIdBPRequests    locAVASecondaryDataAreaIdBPRequests;
    KCS_KBVRequestTable                 locKCS_KBVRequestTable;

    locDataAreaIdCurExt                 = _kcs_KBVRequestTableToCopy.DataAreaId;
    changecompany(locDataAreaIdCurExt)
    {
        locAVASalesParameters               = AVASalesParameters::find();
        locAVASecondaryDataAreaIdBPRequests = locAVASalesParameters.SecondaryDataAreaIdBPRequests;
    }

    changecompany(_dataAreaId)
    {
        buf2buf(_kcs_KBVRequestTableToCopy, this);
        this.initValue();

        /*
        this.KCS_KBVBuildingProjectID   = _kcs_KBVRequestTableToCopy.KCS_KBVBuildingProjectID;
        //this.KCS_KBVRequestStatus       = _kcs_KBVRequestTableToCopy.KCS_KBVRequestStatus;
        //this.KCS_KBVPriority            = _kcs_KBVRequestTableToCopy.KCS_KBVPriority;
        //this.CustRef                    = _kcs_KBVRequestTableToCopy.CustRef;
        this.DirPartyId                 = _kcs_KBVRequestTableToCopy.DirPartyId;
        this.ContactPersonId            = _kcs_KBVRequestTableToCopy.ContactPersonId;
        this.KCS_KBVReceiptDate         = _kcs_KBVRequestTableToCopy.KCS_KBVReceiptDate;
        this.KCS_KBVModifiedDate        = _kcs_KBVRequestTableToCopy.KCS_KBVModifiedDate;
        this.KCS_KBVDeliveryDate        = _kcs_KBVRequestTableToCopy.KCS_KBVDeliveryDate;
        this.KCS_KBVReceiptDate         = _kcs_KBVRequestTableToCopy.KCS_KBVReceiptDate;
        this.KCS_KBVSmmSalesUnitIndoor  = _kcs_KBVRequestTableToCopy.KCS_KBVSmmSalesUnitIndoor;
        this.AVAWorkerSalesTaker        = _kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker;
        this.AVAWorkerSalesTakerDate    = _kcs_KBVRequestTableToCopy.AVAWorkerSalesTakerDate;
        this.KCS_KBVModifiedBy          = _kcs_KBVRequestTableToCopy.KCS_KBVModifiedBy;
        //this.NDX_OriginDataAreaId       = _kcs_KBVRequestTableToCopy.NDX_OriginDataAreaId;
        //this.KCS_KBVDeclinedDate        = _kcs_KBVRequestTableToCopy.KCS_KBVDeclinedDate;
        //this.KCS_KBVDeclinedBy          = _kcs_KBVRequestTableToCopy.KCS_KBVDeclinedBy;
        //this.KCS_KBVDeclinedMemo        = _kcs_KBVRequestTableToCopy.KCS_KBVDeclinedMemo;
        */
        this.NDX_OriginDataAreaId       = _kcs_KBVRequestTableToCopy.NDX_OriginDataAreaId;
        this.KCS_KBVDeclinedDate        = dateNull();
        this.KCS_KBVDeclinedBy          = 0;
        this.KCS_KBVDeclinedMemo        = '';
        this.KCS_KBVPriority            = _kcs_KBVRequestTableToCopy.KCS_KBVPriority;

        if(     _dataAreaId != locDataAreaIdCurExt
            &&  _dataAreaId != ''                   )       // copy to other company 
        {
            this.KCS_KBVModifiedBy          = 0;
            this.KCS_KBVModifiedDate        = dateNull();

            if(locAVASecondaryDataAreaIdBPRequests != '')   // secondary company set
            {
                this.KCS_KBVModifiedBy          = 0;
                this.KCS_KBVModifiedDate        = dateNull();

                if(locAVASecondaryDataAreaIdBPRequests != _dataAreaId  ) // secondary company set and and different to target company
                {
                    this.AVAWorkerSalesTaker        = 0;
                    this.AVAWorkerSalesTakerDate    = dateNull();

                    // check
                    select firstonly locKCS_KBVRequestTable
                    where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == _kcs_KBVRequestTableToCopy.KCS_KBVBuildingProjectID
                        &&  locKCS_KBVRequestTable.AVAWorkerSalesTaker      == _kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker;
                    if(     locKCS_KBVRequestTable.RecId
                        &&  _kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker  )
                    {
                        this.AVAWorkerSalesTaker        = _kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker;
                        this.AVAWorkerSalesTakerDate    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                    }
                }

                if(locAVASecondaryDataAreaIdBPRequests == _dataAreaId  ) // secondary company set and and equal to target company
                {
                    if(_kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker)
                    {
                        this.AVAWorkerSalesTaker        = _kcs_KBVRequestTableToCopy.AVAWorkerSalesTaker;
                        this.AVAWorkerSalesTakerDate    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
                    }
                }
            }
        }
    }
}

/// <summary>
///    Finds the specified record in the <c>KCS_KBVRequestTable</c> table.
/// </summary>
/// <param name="_recordId">
///    The record ID of the <c>KCS_KBVRequestTable</c> record to find.
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>KCS_KBVRequestTable</c> table; otherwise, an empty record.
/// </returns>
public static KCS_KBVRequestTable find( KCS_KBVRequestId    _recordId,
                                        boolean             _forUpdate = false)
{
    KCS_KBVRequestTable record;

    if (_recordId)
    {
        record.selectForUpdate(_forUpdate);

        select firstonly record
        index hint KCS_KBVRequestIDIdx
        where   record.KCS_KBVRequestId == _recordId;
    }

    return record;
}

