}

/// <summary>
///    AVA <c>checkContactPerson</c> method.
/// </summary>
/// <param name="_dirPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <param name="_contactPersonId">
///    <c>ContactPersonId</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
boolean checkContactPerson( DirPartyRecId   _dirPartyId         = this.DirPartyId,
                            ContactPersonId _contactPersonId    = this.ContactPersonId)
{
    ContactPerson   locContactPerson;
    CustAccount     locCustAccount;

    locCustAccount  = CustTable::findByPartyRecId(_dirPartyId).AccountNum;

    if (_contactPersonId)
    {
        locContactPerson = ContactPerson::find(_contactPersonId);

        if (!locContactPerson.ContactPersonId)
        {
            return false;
        }
        if (locContactPerson.ContactForParty != _dirPartyId)
        {
            return false;
        }
        if (locContactPerson.getCustAccount() != locCustAccount)
        {
            return false;
        }
    }
    return true;
}

