/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    switch(_fieldId)
    {
        case fieldNum(KCS_KBVRequestTable, DirPartyId):
            if(!this.checkContactPerson(this.DirPartyId, this.ContactPersonId))
            {
                this.ContactPersonId = '';
            }
            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID, this, _fieldId);
            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID, this, fieldNum(KCS_KBVRequestTable, ContactPersonId));
            break;

        case fieldNum(KCS_KBVRequestTable, ContactPersonId):
            KCS_KBVSearchTable::setFromCommonField(this.KCS_KBVBuildingProjectID, this, _fieldId);
            break;

        case fieldNum(KCS_KBVRequestTable,DirPartyId):
            smmBusRelTable      smmBusRelTable;
            select  firstonly  RecId from smmBusRelTable
            where smmBusRelTable.Party == this.DirPartyId;
            if (!smmBusRelTable.RecId)
            {
                warning(strFmt("@NDX:NXAMissedBusRel",this.DataAreaId,DirPartyTable::findRec(this.DirPartyId).Name));
                this.DirPartyId = 0;
            }
            break;

            default: break;

    }

    super(_fieldId);

}

/// <summary>
///    AVA <c>insert</c> method.
/// </summary>
public void insert()
{
    LogisticsPostalAddress              locLogisticsPostalAddress;
    CustTable                           locCustTable;
    smmSalesDistrictId                  locSmmSalesDistrictId;
    SmmBusRelSalesDistrictGroup         locSmmBusRelSalesDistrictGroup;
    smmBusRelTable                      locSmmBusRelTable;

    KCS_KBVBPCompanySpecific            locKCS_KBVBPCompanySpecific;
    KCS_KBVBuildingProjectTable         locKCS_KBVBuildingProjectTable;

    if (!this.validateWrite())
    {
        throw error("@NDX:NXAErrorRequestNotCreated");
    }


    if (this.KCS_KBVRequestID == '')
    {
        this.KCS_KBVRequestID   = KCS_KBVReqNumber::getSetRequestNumber(this.KCS_KBVBuildingProjectID);
    }

    //Status des BV wird geändert
    //ToDo: KCS_KBVHelpClass::SetBPIfFirstRequestCreated(this.KCS_KBVBuildingProjectID, this.KCS_KBVRequestID, this.dataAreaId);    // KCS/STORS/LU_00002753_Nr. 188/10.12.2009
    //UK-spezifischer Datensatz aktualisieren und anlegen wenn noch nicht vorhanden
    //ToDo: KCS_KBVHelpClass::SetBPCompanySpecificData(this.KCS_KBVBuildingProjectID, this.dataAreaId);                             // KCS/STORS/LU_00002753_SP-Nr. 311/04.11.2009

    // Setzen der Innendienstgruppe
    // Debitor
    locLogisticsPostalAddress   = DirParty::primaryPostalAddress(this.DirPartyId);
    locCustTable                = CustTable::findByPartyRecId(this.DirPartyId);
    if (locCustTable.RecId)
    {
        if (locCustTable.SalesDistrictId)
        {
            locSmmSalesDistrictId   = locCustTable.SalesDistrictId;
        }
        else if (locLogisticsPostalAddress.RecId)
        {
            locSmmBusRelSalesDistrictGroup = AVAKBVHelperClass::ZipCode2SalesDistrict(  locLogisticsPostalAddress.ZipCode,
                                                                                        locLogisticsPostalAddress.CountryRegionId,
                                                                                        curext());
        }
    }
    else
    {
        locSmmBusRelTable = smmBusRelTable::findByParty(this.DirPartyId);
        if (locSmmBusRelTable.RecId)
        {
            if (locSmmBusRelTable.SalesDistrict)
            {
                locSmmSalesDistrictId = locSmmBusRelTable.SalesDistrict;
            }
            else if (locLogisticsPostalAddress.RecId)
            {
                locSmmBusRelSalesDistrictGroup = AVAKBVHelperClass::ZipCode2SalesDistrict(  locLogisticsPostalAddress.ZipCode,
                                                                                            locLogisticsPostalAddress.CountryRegionId,
                                                                                            curext());
            }
        }
    }

    if (!locSmmBusRelSalesDistrictGroup.RecId && locSmmSalesDistrictId)
    {
        locSmmBusRelSalesDistrictGroup = smmBusRelSalesDistrictGroup::avaFind(locSmmSalesDistrictId);
    }

    if (locSmmBusRelSalesDistrictGroup.RecId)
    {
        this.KCS_KBVSmmSalesUnitIndoor = locSmmBusRelSalesDistrictGroup.KCS_KBVSmmSalesUnitIndoor;
    }

    if(!this.AVAWorkerSalesTaker)
    {
        this.AVAWorkerSalesTaker = this.getRelatedAVAWorkerSalesTaker();
        if(this.AVAWorkerSalesTaker)
        {
            this.AVAWorkerSalesTakerDate    = DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone());
            this.KCS_KBVRequestStatus       = KCS_KBVRequestStatus::Assigned;
        }
    }

    super();

    if(this.RecId)
    {
        if(     this.KCS_KBVBuildingProjectID != ''
            &&  !KCS_KBVBPCompanySpecific::exist(this.KCS_KBVBuildingProjectID))
        {
            locKCS_KBVBPCompanySpecific.clear();
            locKCS_KBVBPCompanySpecific.initValue();
            locKCS_KBVBPCompanySpecific.KCS_KBVBuildingProjectID = this.KCS_KBVBuildingProjectID;
            locKCS_KBVBPCompanySpecific.insert();
        }
    }

    locKCS_KBVBuildingProjectTable = KCS_KBVBuildingProjectTable::find(this.KCS_KBVBuildingProjectID);
    if (    locKCS_KBVBuildingProjectTable.RecId 
        &&  locKCS_KBVBuildingProjectTable.KCS_KBVStatus != KCS_KBVStatus::Inquired)
    {
        ttsbegin;
        locKCS_KBVBuildingProjectTable.selectForUpdate(true);
        locKCS_KBVBuildingProjectTable.KCS_KBVStatus = KCS_KBVStatus::Inquired;
        locKCS_KBVBuildingProjectTable.update();
        ttscommit;
    }

    this.setSearchTable();
}

