///    AVA <c>setSearchTable</c> method.
/// </summary>
void setSearchTable()
{
    this.modifiedField(fieldNum(KCS_KBVRequestTable, ContactPersonId));
    this.modifiedField(fieldNum(KCS_KBVRequestTable, DirPartyId));
}

/// <summary>
///    AVA <c>checkRequester</c> method.
/// </summary>
/// <param name="_dirPartyId">
///    <c>DirPartyRecId</c> as type
/// </param>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public static boolean checkRequester(DirPartyRecId _dirPartyId)
{
    CustTable       custTable;
    smmBusRelTable  locSmmBusRelTable;
    boolean         ret = true;

    if (_dirPartyId)
    {
        custTable = CustTable::findByPartyRecId(_dirPartyId);
        if (!custTable)
        {
            locSmmBusRelTable = smmBusRelTable::findByParty(_dirPartyId);
            if (locSmmBusRelTable.RecId)
            {
                if (!locSmmBusRelTable.KCS_RequestEnabled)
                {
                    warning("@NDX:NXAForRequestorOnlyCustomerOrAllowedReltionships");
                    ret = false;
                }
            }
            else
            {
                warning("@NDX:NXAForRequestorOnlyCustomerOrAllowedOfferRecipient");
                ret = false;
            }
        }
        else
        {
            if (custTable.Blocked != CustVendorBlocked::No)
            {
                warning("@NDX:NXALockedRequestorNotAllowed");
                ret = false;
            }
        }
    }
    else
    {
        ret = false;
    }

    return ret;
}

/// <summary>
///    AVA <c>copyRequest</c> method.
/// </summary>
/// <param name="_origId">
///    <c>KCS_KBVRequestID</c> as type
/// </param>
/// <param name="_origDataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
/// <param name="_targetDataAreaId">
///    <c>DataAreaId</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVRequestTable</c> as return value
/// </returns>
public static KCS_KBVRequestTable copyRequest(  KCS_KBVRequestID    _origId,
                                                DataAreaId          _origDataAreaId,
                                                DataAreaId          _targetDataAreaId   )
{
    KCS_KBVRequestTable         origRecord;
    KCS_KBVRequestTable         targetRecord;

    container                   targetDataAreaIdContainer;
    ContactPerson               locContactPerson;
    ContactPersonName           locContactPersonName;

    KCS_KBVInquirerOfTheRequest sourceIoR;
    KCS_KBVInquirerOfTheRequest targetIoR;



    if(_origId)
    {
        targetDataAreaIdContainer = [_origDataAreaId];
        changecompany(_origDataAreaId)
        {
            origRecord              = KCS_KBVRequestTable::find(_origId);
            locContactPerson        = ContactPerson::find(origRecord.ContactPersonId);
            locContactPersonName    = locContactPerson.personName();
        }

        if (origRecord)
        {
            changecompany(_targetDataAreaId)
            {
                if (!KCS_KBVRequestTable::checkRequester(origRecord.DirPartyId))
                {
                    return null;
                }

                targetRecord.clear();
                targetRecord.initValueCopyToUC(origRecord, _targetDataAreaId);

                //targetRecord.ContactPersonId = KCS_KBVRequestTable::findOrCreateContact(_origDataAreaId, _targetDataAreaId, origRecord.ContactPersonId);
                if(targetRecord.DirPartyId && locContactPersonName)
                {
                    targetRecord.ContactPersonId = ContactPerson::avaFindOrCreateCopyNameParty( targetRecord.DirPartyId, 
                                                                                                locContactPersonName, 
                                                                                                locContactPerson.Party  ).ContactPersonId;
                    if(!targetRecord.ContactPersonId)
                    {
                        targetRecord.ContactPersonId = ContactPerson::findOrCreateNameParty(    targetRecord.DirPartyId, 
                                                                                                locContactPersonName    ).ContactPersonId;
                    }
                }
                ttsbegin;
                targetRecord.insert();
                ttscommit;
            }
        }
    }

    // copy IoR`s
    if (targetRecord.RecId)
    {
        ttsbegin;
        while select crosscompany : targetDataAreaIdContainer *
        from    sourceIoR
        where   sourceIoR.KCS_KBVRequestID == _origId
        {
            changecompany(sourceIoR.DataAreaId)
            {
                locContactPerson        = ContactPerson::find(sourceIoR.ContactPersonId);
                locContactPersonName    = locContactPerson.personName();
            }

            changecompany(_targetDataAreaId)
            {
                targetIoR.clear();
                buf2Buf(sourceIoR, targetIoR);

                targetIoR.KCS_KBVRequestID  = targetRecord.KCS_KBVRequestID;
                //targerIoR.ContactPersonId   = KCS_KBVRequestTable::findOrCreateContact(_origDataAreaId, _targetDataAreaId, sourceIoR.ContactPersonId);
                if(targetIoR.DirPartyId && locContactPersonName)
                {
                    targetIoR.ContactPersonId = ContactPerson::avaFindOrCreateCopyNameParty(targetIoR.DirPartyId,
                                                                                            locContactPersonName,
                                                                                            locContactPerson.Party  ).ContactPersonId;
                    if(!targetIoR.ContactPersonId)
                    {
                        targetIoR.ContactPersonId = ContactPerson::findOrCreateNameParty(   targetIoR.DirPartyId,
                                                                                            locContactPersonName    ).ContactPersonId;
                    }
                }
                targetIoR.insert();
            }
        }

        Docu::copy(origRecord, targetRecord);
        ttscommit;
    }


    if (!targetRecord.RecId)
    {
        warning("@NDX:NXARequestCouldNotBeCopied");
    }

    return targetRecord;

}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_dirPartyRecId">_dirPartyRecId</param>
public void createSmmBusRelTableForCompany(DirPartyRecId        _dirPartyRecId, DataAreaId      _dataAreaId = curExt())
{
    smmBusRelTable           locsmmBusRelTable;
    ContactPerson            contactPerson;
    LogisticsPostalAddress   address = DirParty::primaryPostalAddress(_dirPartyRecId);
    CompanyInfo              companyInfo;
    smmBusRelTable           companyBusRelTable;

    List                     companyContactList = new List(Types::Record);
    ListIterator             companyContactListIterator;

    while select companyInfo
        where companyInfo.DataArea != 'DAT'
    {
        changecompany(companyInfo.DataArea)
        {
            ContactPerson            companyContactPerson;
            companyBusRelTable = smmBusRelTable::findByParty(_dirPartyRecId);
            if (companyBusRelTable.RecId)
            {
                while select companyContactPerson
                    where companyContactPerson.ContactForParty == _dirPartyRecId
                {
                    companyContactList.addEnd(companyContactPerson);
                }
                break;
            }
        }
    }
    changecompany(_dataAreaId)
    {
        locsmmBusRelTable.initValue();
        locsmmBusRelTable.initFromDirParty(DirParty::constructFromPartyRecId(_dirPartyRecId));
        locsmmBusRelTable.BusRelAccount = smmParameters::getNumber(smmNumbSeqUsed::BusRel);
        locsmmBusRelTable.Party         = _dirPartyRecId;
        locsmmBusRelTable.NDX_initSalesGroupAndDistrictFromAddr(address.ZipCode, address.CountryRegionId, locsmmBusRelTable.dataAreaId);
        if (companyBusRelTable)
        {
            locsmmBusRelTable.copyFromSmmBusRelTable(companyBusRelTable);
        }
        locsmmBusRelTable.insert();

        ContactPerson            companyContactPerson;
        ContactPerson            checkContactPerson;
        companyContactListIterator = new ListIterator(companyContactList);
        while (companyContactListIterator.more())
        {
            companyContactPerson = companyContactListIterator.value();

            select firstonly RecId from  checkContactPerson
            where checkCOntactPerson.Party == companyContactPerson.Party
            && checkContactPerson.ContactForParty    == companyContactPerson.ContactForParty;

            if (!checkContactPerson.RecId)
            {
                contactPerson.clear();
                contactPerson.initValue();
                //contactPerson.initFromBusRel(companyBusRelTable);
                contactPerson.initFromBusRel(locsmmBusRelTable);
                contactPerson.copyFromCompanyContactPerson(companyContactPerson);
                contactPerson.ContactPersonId  = NumberSeq::newGetNum(ContactPerson::numRefContactPersonId()).num();
                contactPerson.insert();
            }
            companyContactListIterator.next();
        }
    }
}

