/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_hcmWorkerRecId">_hcmWorkerRecId</param>
/// <param name = "_avaReason">_avaReason</param>
/// <returns>boolean</returns>
public boolean assignUnassignRequest(HcmWorkerRecId _hcmWorkerRecId,
                                     AVAReason      _avaReason      = '')
{
    boolean                 retVal;

    KCS_KBVRequestTable     locKCS_KBVRequestTable;
    HcmWorkerRecId          locHcmWorkerRecId;
    date                    locDateToday;
    KCS_KBVRequestStatus    locKCS_KBVRequestStatus;

    locKCS_KBVRequestTable  = this;
    locHcmWorkerRecId       = _hcmWorkerRecId;

    if(locHcmWorkerRecId)
    {
        locKCS_KBVRequestStatus = KCS_KBVRequestStatus::Assigned;
        locDateToday            = AVAKBVBuildingProjectHelper::getToday();
        retVal                  = true;
    }
    else if(    locHcmWorkerRecId           == 0 
            &&  this.AVAWorkerSalesTaker 
            &&  this.KCS_KBVRequestStatus   == KCS_KBVRequestStatus::Assigned)
    {
        if(locHcmWorkerRecId == 0 && _avaReason == '')
        {
            return retVal;
        }

        locKCS_KBVRequestStatus = KCS_KBVRequestStatus::Created;
        locDateToday            = dateNull();
        retVal                  = true;
        AVAKBVDeclineReason::addBPRequestDecline(locKCS_KBVRequestTable.KCS_KBVRequestID, _avaReason);
    }

    if(retVal)
    {
        ttsbegin;
        locKCS_KBVRequestTable.selectForUpdate(true);
        locKCS_KBVRequestTable.AVAWorkerSalesTaker      = locHcmWorkerRecId;
        locKCS_KBVRequestTable.AVAWorkerSalesTakerDate  = locDateToday;
        locKCS_KBVRequestTable.KCS_KBVRequestStatus     = locKCS_KBVRequestStatus;
        locKCS_KBVRequestTable.update();
        this.assignUnassignRequestInfo(locKCS_KBVRequestTable.KCS_KBVRequestID);
        ttscommit;
    }

    return retVal;
}

/// <summary>
///    AVA <c>getNextUnassignedRequest</c> method.
/// </summary>
/// <param name="_hcmWorkerRecId">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <returns>
///    <c>KCS_KBVRequestTable</c> as return value
/// </returns>
public static KCS_KBVRequestTable getNextUnassignedRequest(HcmWorkerRecId _hcmWorkerRecId = HcmWorkerLookup::currentWorker())
{
    KCS_KBVRequestTable retVal;

    smmSalesUnit        locsmmSalesUnit;
    KCS_KBVRequestTable locKCS_KBVRequestTable;

    locsmmSalesUnit = smmSalesUnit::avaGetSalesUnitCurrentWorkerIndoor(_hcmWorkerRecId);

    if(locsmmSalesUnit.RecId)
    {
        select firstonly locKCS_KBVRequestTable
        order by  locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc
        where   locKCS_KBVRequestTable.AVAWorkerSalesTaker          == 0
            &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus         == KCS_KBVRequestStatus::Created
            &&  locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor    == locsmmSalesUnit.SalesUnitId
            &&  locKCS_KBVRequestTable.KCS_KBVPriority              == KCS_KBVPriority::Reminded;

        if(!locKCS_KBVRequestTable.RecId)
        {
            select firstonly locKCS_KBVRequestTable
            order by  locKCS_KBVRequestTable.KCS_KBVPriority desc, locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc
            where   locKCS_KBVRequestTable.AVAWorkerSalesTaker          == 0
                &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus         == KCS_KBVRequestStatus::Created
                &&  locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor    == locsmmSalesUnit.SalesUnitId
                &&  locKCS_KBVRequestTable.KCS_KBVDeliveryDate          <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()); //today();
        }
        if(!locKCS_KBVRequestTable.RecId)
        {
            select firstonly locKCS_KBVRequestTable
            order by  locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc, locKCS_KBVRequestTable.KCS_KBVPriority desc
            where   locKCS_KBVRequestTable.AVAWorkerSalesTaker          == 0
                &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus         == KCS_KBVRequestStatus::Created
                &&  locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor    == locsmmSalesUnit.SalesUnitId;
        }
    }
    else
    {
        select firstonly locKCS_KBVRequestTable
        order by  locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc
        where   locKCS_KBVRequestTable.AVAWorkerSalesTaker          == 0
            &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus         == KCS_KBVRequestStatus::Created
            &&  locKCS_KBVRequestTable.KCS_KBVPriority              == KCS_KBVPriority::Reminded
            join    locsmmSalesUnit
            where   locsmmSalesUnit.SalesUnitId                     == locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor
                &&  locsmmSalesUnit.AVAIndoorServiceControl         == NoYes::No;

        if (!locKCS_KBVRequestTable.RecId)
        {
            select firstonly locKCS_KBVRequestTable
            order by locKCS_KBVRequestTable.KCS_KBVPriority desc, locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc
            where   locKCS_KBVRequestTable.AVAWorkerSalesTaker  == 0
                &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::Created
                &&  locKCS_KBVRequestTable.KCS_KBVDeliveryDate  <= DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()) //today()
                join    locsmmSalesUnit
                where   locsmmSalesUnit.SalesUnitId             == locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor
                    &&  locsmmSalesUnit.AVAIndoorServiceControl == NoYes::No;
        }
        if (!locKCS_KBVRequestTable.RecId)
        {
            select firstonly locKCS_KBVRequestTable
            order by  locKCS_KBVRequestTable.KCS_KBVDeliveryDate asc, locKCS_KBVRequestTable.KCS_KBVPriority desc
            where   locKCS_KBVRequestTable.AVAWorkerSalesTaker  == 0
                &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus == KCS_KBVRequestStatus::Created
                join    locsmmSalesUnit
                where   locsmmSalesUnit.SalesUnitId             == locKCS_KBVRequestTable.KCS_KBVsmmSalesUnitIndoor
                    &&  locsmmSalesUnit.AVAIndoorServiceControl == NoYes::No;
        }
    }

    retVal = locKCS_KBVRequestTable;

    return retVal;
}

/// <summary>
///    AVA <c>assignUnassignRelatedRequests</c> method.
/// </summary>
/// <param name="_hcmWorkerRecIdTo">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <param name="_hcmWorkerRecIdFrom">
///    <c>HcmWorkerRecId</c> as type
/// </param>
/// <param name="_avaReason">
///    <c>AVAReason</c> as type
/// </param>
/// <returns>
///    <c>int</c> as return value
/// </returns>
public int assignUnassignRelatedRequests(   HcmWorkerRecId  _hcmWorkerRecIdTo   = this.AVAWorkerSalesTaker,
                                            HcmWorkerRecId  _hcmWorkerRecIdFrom = 0,
                                            AVAReason       _avaReason          = ''                        )
{
    int                     retVal;
    boolean                 locUpdated;
    HcmWorkerRecId          locHcmWorkerRecIdSearch;
    KCS_KBVRequestTable     locKCS_KBVRequestTable;
    DataAreaId              locDataAreaId;
    KCS_KBVRequestStatus    locKCS_KBVRequestStatusSearch;

    if(_hcmWorkerRecIdTo)
    {   // assign to specific sales taker so search for unassigned entries with status created
        locHcmWorkerRecIdSearch         = 0;
        locKCS_KBVRequestStatusSearch   = KCS_KBVRequestStatus::Created;
    }
    else
    {   // remove assignment so search for assigned entries with status Assigned
        locHcmWorkerRecIdSearch         = _hcmWorkerRecIdFrom;
        locKCS_KBVRequestStatusSearch   = KCS_KBVRequestStatus::Assigned;
    }

    if(     _hcmWorkerRecIdTo       == 0
        &&  locHcmWorkerRecIdSearch == 0    )
    {
        return retVal;
    }

    if(     _hcmWorkerRecIdTo   == 0
        &&  _avaReason          == ''   )
    {
        return retVal;
    }

    ttsbegin;
    while select forupdate locKCS_KBVRequestTable
    where   locKCS_KBVRequestTable.AVAWorkerSalesTaker      == locHcmWorkerRecIdSearch
        &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     == locKCS_KBVRequestStatusSearch
        &&  locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == this.KCS_KBVBuildingProjectID
    {
        locUpdated = locKCS_KBVRequestTable.assignUnassignRequest(_hcmWorkerRecIdTo, _avaReason);
        if(locUpdated)
        {
            retVal++;
        }
    }

    locDataAreaId = AVASalesParameters::find().SecondaryDataAreaIdBPRequests;
    if(locDataAreaId)
    {
        changecompany(locDataAreaId)
        {
            locKCS_KBVRequestTable = null;
            while select forupdate locKCS_KBVRequestTable
            where   locKCS_KBVRequestTable.AVAWorkerSalesTaker      == locHcmWorkerRecIdSearch
                &&  locKCS_KBVRequestTable.KCS_KBVRequestStatus     == locKCS_KBVRequestStatusSearch
                &&  locKCS_KBVRequestTable.KCS_KBVBuildingProjectID == this.KCS_KBVBuildingProjectID
            {
                locUpdated = locKCS_KBVRequestTable.assignUnassignRequest(_hcmWorkerRecIdTo, _avaReason);
                if(locUpdated)
                {
                    retVal++;
                }
            }
        }
    }
    ttscommit;

    return retVal;
}

/// <summary>
///    AVA <c>getRelatedAVAWorkerSalesTaker</c> method.
/// </summary>
/// <returns>
///    <c>AVAWorkerSalesTaker</c> as return value
/// </returns>
AVAWorkerSalesTaker getRelatedAVAWorkerSalesTaker()
{
    AVAWorkerSalesTaker retVal;
    KCS_KBVRequestTable locKCS_KBVRequestTable;
    DataAreaId          locDataAreaId;

    //retVal = HcmWorkerLookup::currentWorker();

    select firstonly locKCS_KBVRequestTable
    order by locKCS_KBVRequestTable.KCS_KBVRequestId desc
    where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectId == this.KCS_KBVBuildingProjectID
        &&  locKCS_KBVRequestTable.AVAWorkerSalesTaker != 0;

    retVal = locKCS_KBVRequestTable.AVAWorkerSalesTaker;

    if(!retVal)
    {
        locDataAreaId = AVASalesParameters::find().SecondaryDataAreaIdBPRequests;
        if(locDataAreaId)
        {
            changecompany(locDataAreaId)
            {
                locKCS_KBVRequestTable = null;
                select firstonly locKCS_KBVRequestTable
                order by locKCS_KBVRequestTable.KCS_KBVRequestId desc
                where   locKCS_KBVRequestTable.KCS_KBVBuildingProjectId == this.KCS_KBVBuildingProjectID
                    &&  locKCS_KBVRequestTable.AVAWorkerSalesTaker != 0;

                retVal = locKCS_KBVRequestTable.AVAWorkerSalesTaker;
            }
        }
    }
    return retVal;
}

/// <summary>
///     AVA <c>displayAvaDocumentAttachedIcon</c> method.
///     AVA - Schneider 16.02.2024
/// </summary>
/// <param name="countAttachments">
///     <c>boolean</c> as type
/// </param>
/// <param name="onlyDocumentsAttached">
///     <c>boolean</c> as type
/// </param>
/// <returns>
///     <c>int64</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display int64 displayAvaDocumentAttachedExists( boolean countAttachments        = false, 
                                                boolean onlyDocumentsAttached   = false)
{
    int64         retVal;

    DocuRef     locDocuRef;
    DocuTypeId  locDocuTypeIdFile;
    DocuTypeId  locDocuTypeIdImage;
    DocuTypeId  locDocuTypeIdRecord;

    retVal = 0;

    if(countAttachments == false)
    {
        if(onlyDocumentsAttached == false)
        {
            select firstonly RecId 
            from    locDocuRef
            where   locDocuRef.RefCompanyId == this.DataAreaId
                &&  locDocuRef.RefTableId   == this.TableId
                &&  locDocuRef.RefRecId     == this.RecId;
        }
        else
        {
            locDocuTypeIdFile   = DocuType::find(DocuType::typeFile()).TypeId;
            locDocuTypeIdImage  = DocuType::find(DocuType::typeImage()).TypeId;

            select firstonly  RecId
            from    locDocuRef
            where   locDocuRef.RefCompanyId == this.DataAreaId
                &&  locDocuRef.RefTableId   == this.TableId
                &&  locDocuRef.RefRecId     == this.RecId
                &&  (   locDocuRef.TypeId == locDocuTypeIdFile
                    ||  locDocuRef.TypeId == locDocuTypeIdImage );
        }
        if(locDocuRef.RecId)
        {
            retVal = 1;
        }
    }
    else
    {
        if(onlyDocumentsAttached == false)
        {
            select count(RecId)
            from    locDocuRef
            where   locDocuRef.RefCompanyId == this.DataAreaId
                &&  locDocuRef.RefTableId   == this.TableId
                &&  locDocuRef.RefRecId     == this.RecId;
        }
        else
        {
            locDocuTypeIdFile   = DocuType::find(DocuType::typeFile()).TypeId;
            locDocuTypeIdImage  = DocuType::find(DocuType::typeImage()).TypeId;

            select count(RecId)
            from    locDocuRef
            where   locDocuRef.RefCompanyId == this.DataAreaId
                &&  locDocuRef.RefTableId   == this.TableId
                &&  locDocuRef.RefRecId     == this.RecId
                &&  (   locDocuRef.TypeId == locDocuTypeIdFile
                    ||  locDocuRef.TypeId == locDocuTypeIdImage );
        }
        retVal = locDocuRef.RecId;
    }

    return retVal;
}

/// <summary>
///     AVA <c>displayAvaDocumentAttachedIcon</c> method.
///     AVA - Schneider 16.02.2024
/// </summary>
/// <returns>
///     <c>container</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display container displayAvaDocumentAttachedIcon()
{
    container       retVal;

    DocuRef         locDocuRef;
    ImageReference  locImageReference;
    int64           locNoOfDocumentsAttached;

    retVal = connull();

    locNoOfDocumentsAttached = this.displayAvaDocumentAttachedExists();

    if(locNoOfDocumentsAttached)
    {
        locImageReference = ImageReference::constructForSymbol(ImageReferenceSymbol::Attach);
    }
    /* alternative with 2 kinds of items dependant on attached files and/or simple notes
    locNoOfDocumentsAttached = this.displayAvaDocumentAttachedExists(false, true);

    if(locNoOfDocumentsAttached)
    {
        locImageReference = ImageReference::constructForSymbol(ImageReferenceSymbol::Attach);
    }
    else
    {
        locNoOfDocumentsAttached = this.displayAvaDocumentAttachedExists();

        if(locNoOfDocumentsAttached)
        {
            locImageReference = ImageReference::constructForSymbol(ImageReferenceSymbol::Note); // ImageReferenceSymbol::GenericDoc);
        }
    }
    */
    if(locImageReference)
    {
        retVal = locImageReference.pack();
    }

    return retVal;
}

